def write():
 inv=json.loads((HERE/'Inventory.json').read_text())
 domains=[dict(zip(('id','domain','existing','quality_freshness','eligibility','presentation','root_causes','commercial_importance','action','refs'),r))for r in D]
 screens=[dict(zip(('focus','commercial_question','currently_presented','elsewhere','root_causes','recover_without_new_research','next_sales_investigation'),r))for r in S]
 recover=[dict(zip(('id','priority','work_type','item','records','refs','root_causes','boundary','commercial_value'),r))for r in R]
 report={'authority':'Owner-readable diagnostic annotations only; no new intelligence registry or decision authority','references':REFS,'domains':domains,'screens':screens,'recoverable_and_backlog':recover}
 (HERE/'Audit.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n')
 for name,rows in [('Coverage',domains),('Traceability',screens),('Recovery-Backlog',recover)]:
  with (HERE/(name+'.csv')).open('w',newline='')as f:
   w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 lines=['# Research coverage: 17 required domains','', 'These are evidence-backed qualitative dispositions, not maturity scores. A record count is not completeness. Root codes are defined in [Methods](Methods-and-Validation.md). Evidence is pinned through [Audit.json](Audit.json) and [Inventory.json](Inventory.json).','']
 for d in domains:
  lines+=['## '+d['id']+' · '+d['domain'],'','- **Held intelligence:** '+d['existing']+'.','- **Quality/freshness:** '+d['quality_freshness']+'.','- **Publication:** '+d['eligibility']+'.','- **Current screen:** '+d['presentation']+'.','- **Root causes:** '+d['root_causes']+'. **Commercial importance:** '+d['commercial_importance']+'.','- **Smallest action:** '+d['action']+'. **Evidence:** '+d['refs']+'.','']
 (HERE/'Coverage.md').write_text('\n'.join(lines))
 lines=['# Research-to-screen diagnosis','','The 16 default subject views plus all 96 allowed focus/detail states are enumerated in Inventory.json. This table adds the commercial question and existing-material handoff. Income/cost/capital detail, credit/service/journey variants, application/partner, programme, objective, source and SWOT details are covered by that finite enumeration; inspection and historical paths are separate owners.','']
 for s in screens:
  m=next(z for z in inv['screens']if z['focus']==s['focus']and not z['detail'])
  lines+=['## '+m['title']+' · '+s['focus'],'','**Question:** '+s['commercial_question'],'','**Current:** '+s['currently_presented']+f". Isolated Main: {m['word_count']} words, {m['regions']} visual targets, {len(m['observed_claim_ids'])} tagged/exact/measure-matched statements. These are bounded diagnostics, not facts-per-screen scores.",'','**Elsewhere:** '+s['elsewhere']+'.','', '**Gap / root:** '+s['root_causes']+'. **Recovery:** '+s['recover_without_new_research']+'.','','**Salesperson discriminator:** '+s['next_sales_investigation'],'']
 lines+=['## Associated drill-downs','','Economics Funding reuses released stocks; Income, Costs, Capital and Divisions have distinct finite views, but unavailable measures are the dominant missing substance. Credit `detail=credit` is an older conceptual detail; `detail=journey-credit` is the layered CEO view. Both remain addressable. Service recovery has FCA legal-bank outcomes, not a Group customer-quality diagnosis. Envoy/Copilot detail separates source-supported disclosure from missing installation/contract information. Programme and objective details preserve unknown funding/mandate/progress. SWOT theme details retain counter-evidence. Optional source views expose provenance and are not primary executive navigation.','','Default applications has two platform/licence examples; the only verified current relationship is the reported Group–Google collaboration. Default capability and operating screens can have many targets but no direct company-specific claim in their bodies. The absence is therefore not solved by adding another navigation surface.']
 (HERE/'Traceability.md').write_text('\n'.join(lines)+'\n')
 print(json.dumps({'domains':len(domains),'screen_assessments':len(screens),'backlog':len(recover)}))
if __name__=='__main__':write()
